mapper.update:
    UPDATE 
    	   TB_REVIEW
       SET 
           REVIEW_TITLE = #{reviewTitle}
         , REVIEW_CONTENT = #{reviewContent}
     WHERE 
     	   REVIEW_NO = #{reviewNo}
       AND 
       	   STATION_NO = #{stationNo} 
	   AND 
	       MEMBER_NO = #{memberNo} 
       AND 
       	   STATUS = 'Y'
